// FUNCTION: BFME2 0x0003F550 size=115 name=?Read@DebugIONet@@UAEHPADH@Z evidence=N:ledger tier=L hypothesis:name:L
int DebugIONet::Read(char *buf, int maxchar)
{
	if (m_pipe == INVALID_HANDLE_VALUE)
		return 0;

	unsigned long mode = PIPE_READMODE_MESSAGE | PIPE_NOWAIT;
	SetNamedPipeHandleState(m_pipe, &mode, 0, 0);

	unsigned long read;
	if (!ReadFile(m_pipe, buf, maxchar - 1, &read, 0))
		read = 0;
	mode = PIPE_READMODE_MESSAGE | PIPE_WAIT;
	SetNamedPipeHandleState(m_pipe, &mode, 0, 0);

	return read;
}


// FUNCTION: BFME2 0x0003F5D0 size=188 name=?Write@DebugIONet@@UAEXW4StringType@DebugIOInterface@@PBD1@Z evidence=N:ledger tier=L hypothesis:name:L
void DebugIONet::Write(StringType type, const char *src, const char *str)
{
	if (m_pipe == INVALID_HANDLE_VALUE)
		return;

	unsigned long dummy;
	WriteFile(m_pipe, &type, 1, &dummy, 0);

	unsigned len;
	len = src ? strlen(src) : 0;
	WriteFile(m_pipe, &len, 4, &dummy, 0);
	if (len)
		WriteFile(m_pipe, src, len, &dummy, 0);

	len = strlen(str);
	WriteFile(m_pipe, &len, 4, &dummy, 0);
	if (len)
		WriteFile(m_pipe, str, len, &dummy, 0);
}


// FUNCTION: BFME2 0x0003F690 size=283 name=?Execute@DebugIONet@@UAEXAAVDebug@@PBD_NIPBQBD@Z evidence=N:ledger tier=B hypothesis:cohesion
void DebugIONet::Execute(Debug &dbg, const char *cmd, bool structuredCmd, unsigned int argn, const char *const *argv)
{
	if (!cmd || !strcmp(cmd, "help"))
	{
		dbg << "net I/O help:\n"
			   "  add [ <machine> ]\n"
			   "    create net I/O (optionally specifying the machine to connect to)\n";
	}
	else if (!strcmp(cmd, "add"))
	{
		const char *machine = argn ? argv[0] : ".";

		char buf[256];
		wsprintfA(buf, "\\\\%s\\pipe\\ea_debug_v1", machine);
		m_pipe = CreateFileA(buf, GENERIC_READ | GENERIC_WRITE, 0, 0, OPEN_EXISTING, 0, 0);
		if (m_pipe == INVALID_HANDLE_VALUE)
		{
			dbg << "Could not connect to given machine.\n";
			return;
		}

		// we're reading messages
		unsigned long mode = PIPE_READMODE_MESSAGE;
		SetNamedPipeHandleState(m_pipe, &mode, 0, 0);

		// write welcome message
		char comp[128];
		mode = sizeof(comp);
		GetComputerNameA(comp, &mode);
		wsprintfA(buf, "Client at %s\n", comp);
		Write(Other, 0, buf);
	}
}


